FONCTION Entraînement_Memoire(Données_Entraînement, Hyperparamètres):
    INITIALISER M_0 (État de mémoire initial)
    POUR chaque échantillon (X, Y) DANS Données_Entraînement:
        // Initialiser les états pour l'échantillon
        M_t = M_{t-1}  // Utilisation de l'état précédent

        // 1. Calculer la sortie du modèle (simulé)
        H = Transformer(X, M_t) 

        // 2. Calculer la perte de modélisation du langage
        L_lm = Calculer_Perte_LM(Y, H)

        // 3. Calculer le terme contrastif (nécessite des embeddings et une méthode de contraste)
        H_contrastive = Calculer_Embeddings(H) 
        L_contrastive = Calculer_Perte_Contrastive(H_contrastive, ...)

        // 4. Calculer la perte totale
        L = L_lm + lambda * L_contrastive

        // 5. Mise à jour de la mémoire (via le mécanisme de gating)
        // Le mécanisme de gating g_t doit être dérivé des sorties H ou d'un autre état.
        g_t = Calculer_Gating(H, M_t) 
        M_{t+1} = M_t * g_t + v_t * (1 - g_t)

    RETOURNER Moyenne(L)

FONCTION Mise_a_Jour_Memoire(M_t, g_t, v_t):
    // Règle de mise à jour par gating
    Nouveau_M = M_{t-1} * g_t + v_t * (1 - g_t)
    RETOURNER Nouveau_M

